## Code Example

```javascript
// Minimal example to compute anchor-based metric
function computeAnchorMetric(attn, starts) {
  // attn: 2D array [t_len][s_len]
  // starts: Set of source indices that are word starts
  let score = 0;
  for (let t = 0; t < attn.length; t++) {
    let sumAnchor = 0;
    for (let s = 0; s < attn[t].length; s++) {
      if (starts.has(s)) sumAnchor += attn[t][s];
    }
    score += sumAnchor;
  }
  return attn.length ? score / attn.length : 0;
}
```

